repo_files.src/auth.py:
import threading

_LOCK = threading.Lock()
_CACHE = {}


class TokenStore:
    def __init__(self, ttl):
        self.ttl = ttl

    def lookup(self, key):
        with _LOCK:
            value = _CACHE.get(key)
        return value


def refresh_token(scope):
    token = f"{scope}-token"
    return token

